<?php

namespace Ediligence\EdiligenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * TreceptionRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TreceptionRepository extends \Doctrine\ORM\EntityRepository
{
   public function registre($service_sup, $agent) {
      $qb = $this->createQueryBuilder('r')
                 ->addSelect('(CASE WHEN t.id IS NOT NULL THEN 1 ELSE 0 END )as etat, i.dateImput, i.delaiImput')
                 ->InnerJoin("EdiligenceBundle:Timputations", 'i',  Join::WITH,'i.id = r.idImput')
                 ->LeftJoin("EdiligenceBundle:Tmp_traitement", 't',  Join::WITH,'r.idImput = t.idImput')
                 ->where('r.matriculereception =:matriculereception And r.servicereception =:servicereception')
                 ->andWhere('t.idImput Is Null')
                 ->setParameter("matriculereception", $agent)
                 ->setParameter("servicereception", $service_sup);
      return $qb->getQuery()->getResult();

    }   
    
    
}
